 p=subprocess.run([PSQL,'-X','-w','-qAt','-h','/run/postgresql','-d','etp_carnet','-v','ON_ERROR_STOP=1'],input=QUERY.encode(),stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,timeout=10,preexec_fn=identity,env={'LC_ALL':'C','PGCONNECT_TIMEOUT':'5'})
